/**
 * Type-checks the code the site shows, against clients generated by this checkout:
 *
 * - hand-written samples in `samples/<variant>/` (included by MDX pages), and
 * - code blocks in `docs/*.md` and `README.md` whose info string says `check`
 *   (```ts check, or ```ts check=axios for another variant), extracted into `samples/.extracted/`.
 *
 * Each variant is a generated client in `samples/<variant>/generated/api`; samples import it as
 * `./generated/api`, as the docs do. Errors are reported at the line of the Markdown file.
 */
import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import ts from 'typescript';
import { loadConfig } from '../../src/config/load.ts';
import type { UserConfig } from '../../src/config/types.ts';
import { compile } from '../../src/pipeline/compile.ts';
import { ROOT, WEBSITE } from './data/output.ts';

const SAMPLES = path.join(WEBSITE, 'samples');
const EXTRACTED = path.join(SAMPLES, '.extracted');

const petstore = {
  version: '3.0',
  input: path.join(ROOT, 'fixtures', 'specs', 'petstore-3.0.yaml'),
} as const;

/** The clients samples are checked against. */
const VARIANTS: Record<string, UserConfig> = {
  default: { spec: petstore, features: { query: true, validation: 'zod' } },
  axios: { spec: petstore, client: { adapter: 'axios' } },
  full: { spec: petstore, client: { responseStyle: 'full' } },
  swr: { spec: petstore, features: { swr: true } },
  vue: { spec: petstore, features: { query: { framework: 'vue' } } },
  dates: {
    spec: { version: '3.1', input: path.join(WEBSITE, 'twins', 'dates.yaml') },
    types: { dates: 'Date' },
  },
  bodies: { spec: { version: '3.1', input: path.join(WEBSITE, 'twins', 'bodies.yaml') } },
  webhooks: { spec: { version: '3.1', input: path.join(WEBSITE, 'twins', 'webhook.yaml') } },
  servers: { spec: { version: '3.1', input: path.join(WEBSITE, 'twins', 'servers.yaml') } },
  'read-write': { spec: { version: '3.1', input: path.join(WEBSITE, 'twins', 'read-write.yaml') } },
};

/** Markdown files whose `check` code blocks are compiled. */
async function markdownSources(): Promise<string[]> {
  const docs = (await readdir(path.join(ROOT, 'docs')))
    .filter((name) => name.endsWith('.md'))
    .map((name) => `docs/${name}`);
  return ['README.md', ...docs].sort();
}

interface Extracted {
  readonly file: string;
  readonly source: string;
  /** Line of the Markdown file where the code starts. */
  readonly line: number;
}

async function generateVariant(name: string, config: UserConfig): Promise<void> {
  const directory = path.join(SAMPLES, name, 'generated', 'api');
  await rm(directory, { recursive: true, force: true });
  const loaded = await loadConfig({ cwd: SAMPLES, inlineConfig: config, env: {} });
  const result = await compile({ config: loaded.config, plugins: loaded.plugins });
  if (!result.ok) {
    throw new Error(
      `The sample client "${name}" does not compile: ${result.diagnostics
        .filter((d) => d.severity === 'error')
        .map((d) => `${d.code} ${d.message}`)
        .join('; ')}`,
    );
  }
  for (const file of result.files) {
    const target = path.join(directory, file.path);
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, file.content);
  }
}

async function extract(source: string): Promise<Extracted[]> {
  const lines = (await readFile(path.join(ROOT, source), 'utf8')).split('\n');
  const out: Extracted[] = [];
  for (let index = 0; index < lines.length; index++) {
    const open = /^```(ts|tsx)\s+check(?:=([a-z-]+))?\s*$/.exec(lines[index] ?? '');
    if (open === null) continue;
    const [, language = 'ts', variant = 'default'] = open;
    if (VARIANTS[variant] === undefined) {
      throw new Error(`${source}:${index + 1}: unknown sample variant "${variant}"`);
    }
    const start = index + 1;
    let end = start;
    while (end < lines.length && !/^```\s*$/.test(lines[end] ?? '')) end++;
    const code = lines
      .slice(start, end)
      .join('\n')
      .replace(/(['"])\.\/generated\/api/g, `$1../../${variant}/generated/api`);
    const name = `${source.replace(/[/.]/g, '_')}_L${start + 1}.${language}`;
    const file = path.join(EXTRACTED, variant, name);
    await mkdir(path.dirname(file), { recursive: true });
    // `export {}` keeps every snippet a module of its own.
    await writeFile(file, `${code}\nexport {};\n`);
    out.push({ file, source, line: start + 1 });
    index = end;
  }
  return out;
}

async function handWritten(): Promise<string[]> {
  const files: string[] = [];
  for (const variant of Object.keys(VARIANTS)) {
    const directory = path.join(SAMPLES, variant);
    const entries = await readdir(directory).catch(() => [] as string[]);
    for (const entry of entries) {
      if (/\.(ts|tsx)$/.test(entry)) files.push(path.join(directory, entry));
    }
  }
  return files.sort();
}

export async function checkSamples(): Promise<number> {
  await rm(EXTRACTED, { recursive: true, force: true });
  await Promise.all(
    Object.entries(VARIANTS).map(([name, config]) => generateVariant(name, config)),
  );
  const extracted = (await Promise.all((await markdownSources()).map(extract))).flat();
  const files = [...(await handWritten()), ...extracted.map((item) => item.file)];
  const program = ts.createProgram(files, {
    strict: true,
    exactOptionalPropertyTypes: true,
    noUncheckedIndexedAccess: true,
    noEmit: true,
    skipLibCheck: true,
    target: ts.ScriptTarget.ES2022,
    lib: ['lib.es2022.d.ts', 'lib.dom.d.ts', 'lib.dom.iterable.d.ts'],
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    jsx: ts.JsxEmit.ReactJSX,
    types: [],
    verbatimModuleSyntax: true,
    isolatedModules: true,
  });
  const diagnostics = ts.getPreEmitDiagnostics(program);
  const bySample = new Map(extracted.map((item) => [path.resolve(item.file), item]));
  const messages = diagnostics.map((diagnostic) => {
    const text = ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n');
    if (diagnostic.file === undefined || diagnostic.start === undefined) return text;
    const { line } = diagnostic.file.getLineAndCharacterOfPosition(diagnostic.start);
    const sample = bySample.get(path.resolve(diagnostic.file.fileName));
    const where =
      sample === undefined
        ? `${path.relative(ROOT, diagnostic.file.fileName)}:${line + 1}`
        : `${sample.source}:${sample.line + line}`;
    return `${where}: ${text}`;
  });
  if (messages.length > 0) {
    throw new Error(
      `Code samples do not type-check:\n${messages.map((m) => `  - ${m}`).join('\n')}`,
    );
  }
  return files.length;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const count = await checkSamples();
  console.log(`Type-checked ${count} code samples.`);
}
